import 'package:flutter/foundation.dart';
import 'package:flutter/material.dart';
import 'package:flutter/services.dart';

/// Attribution, not a licence grant. scripts/licenses/notices.py check
/// fails if this wording drifts from THIRD_PARTY_NOTICES.txt.
const kShearAttribution =
    'The Shear concept was inspired by Roy D Herbert, and the Chronoflux Principia.';

const kShearLegalese = 'Shear is released under the MIT License. Copyright (c) 2026 Shear.\n\n'
    '$kShearAttribution\n\n'
    'This is an attribution, not a licence grant.';

/// Generated by scripts/licenses/notices.py. Flutter already lists each Dart
/// package's top-level LICENSE, so this asset carries everything else: the
/// Rust crates in libshear_admit, libsodium, the Node.js sidecar and its npm
/// packages, Android and iOS native libraries, and extra Dart licence files.
const kThirdPartyNoticesAsset = 'assets/licenses/THIRD_PARTY_NOTICES.txt';

final _rule = '=' * 80;
final _sub = '-' * 80;

/// One [LicenseEntry] per section of THIRD_PARTY_NOTICES.txt.
List<LicenseEntry> parseThirdPartyNotices(String text) {
  final out = <LicenseEntry>[];
  final blocks = text.replaceAll('\r\n', '\n').split('\n$_rule\n');
  for (final block in blocks.skip(1)) {
    final split = block.indexOf('\n$_sub\n');
    if (split < 0) continue;
    final header = block.substring(0, split).split('\n');
    final body = block.substring(split + _sub.length + 2).trimRight();
    final packages = <String>[];
    for (final line in header) {
      if (line.startsWith('PACKAGES: ')) {
        packages.addAll(line.substring('PACKAGES: '.length).split('; ').where((p) => p.isNotEmpty));
      }
    }
    if (packages.isEmpty || body.isEmpty) continue;
    out.add(LicenseEntryWithLineBreaks(packages, body));
  }
  return out;
}

bool _registered = false;

/// Adds the bundled notices to Flutter's [LicenseRegistry] once.
void registerShearLicenses({AssetBundle? bundle}) {
  if (_registered) return;
  _registered = true;
  LicenseRegistry.addLicense(() async* {
    final text = await (bundle ?? rootBundle).loadString(kThirdPartyNoticesAsset);
    for (final entry in parseThirdPartyNotices(text)) {
      yield entry;
    }
  });
}

@visibleForTesting
void debugResetShearLicenses() {
  _registered = false;
}

void showShearLicenses(BuildContext context, {required String version}) {
  registerShearLicenses();
  showLicensePage(
    context: context,
    applicationName: 'Shear Continuum',
    applicationVersion: version,
    applicationLegalese: kShearLegalese,
  );
}
